const STYLE = {
  beginner: 'The listener is new to this. Explain like a smart friend: plain words, short sentences, at most one number per sentence.',
  intermediate: 'The listener follows the news. Compact and clear, normal financial vocabulary.',
  expert: 'The listener is an expert. Dense and precise: comparisons, exact figures and qualifiers, no definitions.',
