const TONE = {
  calm: 'CALM: warm and unhurried. Longer, flowing sentences (15-25 words), gentle transitions, room to breathe; address the listener softly ("Here is what happened.").',
  neutral: 'CLEAR: like a good business podcast host - crisp, confident, medium-length sentences, no hype.',
  energetic: 'ENERGETIC: lively and punchy. Short sentences (6-14 words), strong verbs, a direct "you" now and then, the occasional short exclamation - still precise.',
}[P.tone];
const FORMAT = {
  explainer: `FORMAT "Explainer" - the listener is new to this. Explain each story from the start: who, what, why it matters. At most ${P.numbers_per_sentence || 1} number per sentence, and only the number that carries the point - say the rest in words ("almost doubled", "a huge petition"). Use "background" segments for concepts they need.`,
  story: `FORMAT "Story" - tell each story as a story: the situation, the turn, why it matters. At most ${P.numbers_per_sentence || 2} numbers per sentence; numbers only where they carry the point.`,
  desk: `FORMAT "Market desk" - a dense, fast rundown for someone who knows the field: lead with what moved, key figures and comparisons, what to watch. At most ${P.numbers_per_sentence || 4} numbers per sentence. No definitions, no background segments.`,
}[P.format] || '';
